from itertools import product
from math import exp
from collections import defaultdict
sigmoid=lambda x:1/(1+exp(-x))
# Integrate the shared Uniform latent U1 in the manuscript's Bernoulli equations.
p_hv={(0,0):1/6,(0,1):1/3,(1,0):1/3,(1,1):1/6}
p={}
for h,v,c,r,y in product([0,1],repeat=5):
 pr=sigmoid(.75*h+.5*c)
 py=sigmoid(-.5+2.5*v+1.75*c)
 p[h,v,c,r,y]=p_hv[h,v]*.5*(pr if r else 1-pr)*(py if y else 1-py)
def conditional_y(**given):
 index={'h':0,'v':1,'c':2,'r':3}
 matching=[(state,prob) for state,prob in p.items() if all(state[index[k]]==val for k,val in given.items())]
 return sum(prob for state,prob in matching if state[4]==1)/sum(prob for _,prob in matching)
print('From the printed simulation equations:')
